#!/usr/bin/env python3
"""Trim the libdl kernel symbol table generated by rtems-syms.

Usage: libdl_syms_filter.py <nm> <syms.c> <libdir> [<libdir> ...]

rtems-syms -e writes a C file whose asm block lists every global symbol of
the pre-linked kernel as a pair of lines

    "  .asciz \"name\"\n"
    "  " SYM_VALUE " name\n"

The second line is a real reference, so linking the table into the final
kernel pulls in whatever defines each name. A few names are defined in
more than one archive member (libbsd's _bsd_dwc_otg_driver in the nexus
and the fdt glue, RTEMS configuration objects, ...). Referencing those by
name can drag the alternative member into the link and fail with
"multiple definition". Loadable modules do not need such symbols, so this
script removes from the table

  * every non-weak global that is defined in more than one member of the
    archives found in the given library directories, and
  * every symbol matching one of the EXCLUDE patterns below (libbsd and
    RTEMS internals that are not an API for modules).

The file is rewritten in place; a summary goes to stdout.
"""
import glob
import os
import re
import subprocess
import sys

EXCLUDE = [
    r"^_bsd_",            # libbsd internals (FreeBSD kernel symbols)
    r"^rtems__rtl_",      # the table itself
    r"^__TLS_",
]


def multiply_defined(nm, libdirs):
    seen = {}
    for d in libdirs:
        for lib in sorted(glob.glob(os.path.join(d, "*.a"))):
            if os.path.basename(lib) in ("librtemsdefaultconfig.a", "librtemsCom.a", "librtemstest.a"):
                continue        # never linked (defaults the application's rtems_config.o replaces)
            try:
                out = subprocess.run([nm, "--defined-only", "-g", "-A", lib],
                                     capture_output=True, text=True, check=False).stdout
            except OSError as e:
                sys.exit("libdl_syms_filter: cannot run %s: %s" % (nm, e))
            for line in out.splitlines():
                parts = line.split()
                if len(parts) < 3:
                    continue
                member, typ, name = parts[0], parts[-2], parts[-1]
                if typ in "TDRB":                      # strong definitions only
                    seen.setdefault(name, set()).add(member)
    return {n for n, members in seen.items() if len(members) > 1}


def main():
    if len(sys.argv) < 4:
        sys.exit(__doc__)
    nm, path, libdirs = sys.argv[1], sys.argv[2], sys.argv[3:]
    # Names strongly defined in more than one archive member used to be
    # dropped so that the table's references would not pull a second copy
    # into the second link. With the API roots of libdl_api_symbols.py the
    # first link already holds one definition of each and the second link
    # resolves the table against it (verified 2026-10-20: 0 duplicates), so
    # the rule is off; multiply_defined() is kept for diagnosis.
    dups = set()
    excl = [re.compile(p) for p in EXCLUDE]

    with open(path) as f:
        lines = f.readlines()
    out, i, removed, kept = [], 0, [], 0
    asciz = re.compile(r'^"  \.asciz \\"(.+)\\"\\n"$')
    while i < len(lines):
        m = asciz.match(lines[i].rstrip("\n"))
        if m and i + 1 < len(lines) and "SYM_VALUE" in lines[i + 1]:
            name = m.group(1)
            if name in dups or any(p.search(name) for p in excl):
                removed.append(name)
                i += 2
                continue
            kept += 1
            out.append(lines[i]); out.append(lines[i + 1])
            i += 2
            continue
        out.append(lines[i])
        i += 1
    # The table carries a list of thread-local symbols addressed by INDEX
    # into the entry list (RTEMS_TLS_INDEX_<name> defines, used by
    # rtems_rtl_tls_offsets[]). Removing entries shifts every later index,
    # and the loader would then hand a TLS offset (a small number) to
    # whatever symbol slid into that slot: 2026-10-20 rtems_libio_number_iops
    # and rtems_libio_iops became 0x814/0x840 and iocStats crashed at
    # iocInit. Renumber the defines from the kept entries; a TLS symbol that
    # was itself removed loses its offset entry and accessor.
    kept_names = []
    for line in out:
        m = asciz.match(line.rstrip("\n"))
        if m:
            kept_names.append(m.group(1))
    index_of = {n: i for i, n in enumerate(kept_names)}
    text = "".join(out)
    dropped_tls = []
    def renumber(m):
        name = m.group(1)
        if name in index_of:
            return "#define RTEMS_TLS_INDEX_%s %d" % (name, index_of[name])
        dropped_tls.append(name)
        return "/* TLS symbol %s filtered out */" % name
    text = re.sub(r"#define RTEMS_TLS_INDEX_(\w+)\s+\d+", renumber, text)
    for name in dropped_tls:
        text = re.sub(r"  \{ RTEMS_TLS_INDEX_%s, rtems_rtl_tls_%s \},\n" % (re.escape(name), re.escape(name)), "", text)
        text = re.sub(r"static size_t rtems_rtl_tls_%s\(void\) \{\n(?:.*\n){3}\}\n" % re.escape(name), "", text)
    with open(path, "w") as f:
        f.write(text)
    tls_total = len(re.findall(r"#define RTEMS_TLS_INDEX_", text))
    print("libdl_syms_filter: %d TLS index entries renumbered, %d dropped with their symbols"
          % (tls_total, len(dropped_tls)))
    print("libdl_syms_filter: %d symbols kept, %d removed (%d multiply defined "
          "in %d library dirs, %d by pattern)" % (
              kept, len(removed), len([n for n in removed if n in dups]),
              len(libdirs), len([n for n in removed if n not in dups])))


if __name__ == "__main__":
    main()
